import React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { updateField } from '../redux/formSlice';

export default function StepOne({ next }) {
  const dispatch = useDispatch();
  const { firstName, lastName, email } = useSelector((state) => state.form);

  return (
    <div>
      <input placeholder="First Name" value={firstName} onChange={(e) => dispatch(updateField({ field: 'firstName', value: e.target.value }))} />
      <input placeholder="Last Name" value={lastName} onChange={(e) => dispatch(updateField({ field: 'lastName', value: e.target.value }))} />
      <input placeholder="Email" value={email} onChange={(e) => dispatch(updateField({ field: 'email', value: e.target.value }))} />
      <button onClick={next}>Next ➜</button>
    </div>
  );
}
